
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_m06_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_m06", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.009052478664843e-01, -9.911821622568999e-02, -9.654893970233068e-02, -9.286239509747733e-02, -8.760004243965730e-02, -8.018536710778632e-02, -7.007356047659895e-02, -5.736678614840419e-02, -4.413102177062782e-02, -3.325600273716006e-02, -3.175549596955109e-02, -1.257167914356858e-01, -3.366290394617950e-02, -2.142114371605695e-02, -1.181723073491395e-02, 4.601772786697777e-03, -3.219344528620400e-03, -2.560974067121202e-03, -4.575393756207172e-04, -3.449267197182777e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


